async function loadIndustryCenter(){try{const d=await API.getIndustryDashboard(adminPin);['partners','activities','guestAttendance','visitAttendance','internships','verifiedInternships'].forEach(k=>{const el=$('ic'+({partners:'Partners',activities:'Activities',guestAttendance:'GuestAtt',visitAttendance:'VisitAtt',internships:'Internships',verifiedInternships:'Verified'}[k]));if(el)el.textContent=d[k]||0;});const q=$('industrySearch')?.value.trim()||'';const [acts,ins,ps]=await Promise.all([API.getIndustryActivities(adminPin,{search:q}),API.getInternships(adminPin,{search:q}),API.getIndustryPartners(adminPin,{search:q})]);$('industryActivityRows').innerHTML=(acts||[]).map(x=>`<tr><td>${esc(x['Activity Type'])}</td><td>${esc(x.Title)}</td><td>${esc(x.Class)}</td><td>${esc(x.Trade)}</td><td>${esc(x.Date)}</td><td>${esc(x['Partner/Guest'])}</td><td>${esc(x.Status)}</td><td><button class="mini" onclick='editIndustryActivity(${JSON.stringify(x).replace(/</g,'\\u003c')})'>Edit</button> <button class="mini" onclick='openAttendance("${esc(x['Activity ID'])}","${esc(x['Activity Type'])}")'>Attendance</button> <button class="mini danger" onclick='deleteIndustryActivity("${esc(x['Activity ID'])}")'>Delete</button></td></tr>`).join('')||'<tr><td colspan="8">No activities yet.</td></tr>';$('internshipRows').innerHTML=(ins||[]).map(x=>`<tr><td>${esc(x['Student Name'])}</td><td>${esc(x.Class)}</td><td>${esc(x['Roll Number'])}</td><td>${esc(x.Organization)}</td><td>${esc(x.Role)}</td><td>${esc(x['Start Date'])} → ${esc(x['End Date'])}</td><td>${esc(x.Status)}</td><td>${String(x.Verified).toLowerCase()==='yes'?'✅':'⏳'}</td><td><button class="mini" onclick='editInternship(${JSON.stringify(x).replace(/</g,'\\u003c')})'>Edit</button> <button class="mini danger" onclick='deleteInternship("${esc(x['Internship ID'])}")'>Delete</button></td></tr>`).join('')||'<tr><td colspan="9">No internships yet.</td></tr>';$('partnerRows').innerHTML=(ps||[]).map(x=>`<tr><td>${esc(x.Organization)}</td><td>${esc(x.Type)}</td><td>${esc(x['Contact Person'])}</td><td>${esc(x.Location)}</td><td>${esc(x['Industry/Domain'])}</td><td>${esc(x.Status)}</td><td><button class="mini" onclick='editPartner(${JSON.stringify(x).replace(/</g,'\\u003c')})'>Edit</button> <button class="mini danger" onclick='deletePartner("${esc(x['Partner ID'])}")'>Delete</button></td></tr>`).join('')||'<tr><td colspan="7">No industry partners yet.</td></tr>';}catch(e){msg(e.message,'error');}}
