async function loadSkillCenter(){
  const box=$('skillCenterRows'); if(!box)return;
  try{
    const rows=await API.getSkillRecords(adminPin, {search:$('skillCenterSearch')?.value.trim()||''});
    box.innerHTML=(rows||[]).map(x=>`<tr><td>${esc(x['Student Name'])}</td><td>${esc(x.Class)}</td><td>${esc(x['Roll Number'])}</td><td>${esc(x['Skill Name'])}</td><td>${esc(x.Level)}%</td><td>${String(x.Verified).toLowerCase()==='yes'?'✅ Verified':'⏳ Pending'}</td><td><button class="mini" onclick="editCentralSkill('${esc(x.ID)}')">Edit</button> <button class="mini danger" onclick="deleteCentralSkill('${esc(x.ID)}')">Delete</button></td></tr>`).join('')||'<tr><td colspan="7">No central skill records yet.</td></tr>';
  }catch(e){box.innerHTML='<tr><td colspan="7">'+esc(e.message)+'</td></tr>';}
}
