function printCentralCertificate(x){const w=window.open('','_blank');if(!w)return;w.document.write(`<!doctype html><html><head><title>${esc(x['Certificate ID'])}</title><style>body{font-family:Arial;padding:50px}.cert{border:8px double #1f3a5f;padding:55px;text-align:center;min-height:650px}.id{font-size:12px;color:#667085}.name{font-size:34px;font-weight:700;margin:24px}.title{font-size:26px;font-weight:700}.skill{font-size:20px;margin:25px}.row{display:flex;justify-content:space-between;margin-top:90px;font-size:14px}</style></head><body><div class="cert"><div class="id">CERTIFICATE ID: ${esc(x['Certificate ID'])}</div><h1>Govt. Sandipani HSS School Damoh</h1><div class="title">${esc(x['Certificate Title'])}</div><p>This certificate recognizes the vocational achievement of</p><div class="name">${esc(x['Student Name'])}</div><p>Class ${esc(x.Class)} • Roll No. ${esc(x['Roll Number'])} • ${esc(x.Trade)}</p><div class="skill"><b>Skill / Competency:</b><br>${esc(x['Skill/Competency']||'Vocational Skill')}</div><p>Level: ${esc(x.Level)} • Verification: ${esc(x['Verification Status'])}</p><div class="row"><span>Issued: ${esc(x['Issued At'])}</span><span>Issued By: ${esc(x['Issued By'])}</span></div></div><script>window.print()<\\/script></body></html>`);w.document.close();}


// ---------------- ADMISSION TEST & MERIT CENTER ----------------
let admissionTestsCache=[], admissionMeritCache=[], admissionSelectedTest='';
async function loadAdmissionCenter(){
  try{
    admissionTestsCache=await API.getAdmissionTests(adminPin)||[];
    const sel=$('admissionTestSelect');
    if(sel){const current=admissionSelectedTest||sel.value;sel.innerHTML='<option value="">Select Admission Test</option>'+admissionTestsCache.map(x=>`<option value="${esc(x['Test ID'])}">${esc(x['Academic Year'])} • ${esc(x.Class)} • ${esc(x.Trade)} • ${esc(x['Job Role'])} • ${esc(x['Test ID'])}</option>`).join('');if(current&&admissionTestsCache.some(x=>x['Test ID']===current))sel.value=current;}
    $('admissionTestRows').innerHTML=admissionTestsCache.map(x=>`<tr><td>${esc(x['Test ID'])}</td><td>${esc(x['Academic Year'])}</td><td>${esc(x.Class)}</td><td>${esc(x.Trade)}</td><td>${esc(x['Job Role'])}</td><td>${esc(x['Test Date'])}</td><td>${esc(x['Total Seats'])}</td><td>${esc(x['Max Marks'])}</td><td><span class="badge">${esc(x.Status)}</span></td><td><button class="mini" onclick='selectAdmissionTest("${esc(x['Test ID'])}")'>Open</button> <button class="mini" onclick='openAdmissionQuestions("${esc(x['Test ID'])}")'>Questions</button> <button class="mini" onclick='toggleAdmissionStatus("${esc(x['Test ID'])}")'>${String(x.Status).toLowerCase()==='open'?'Close':'Open'}</button> <button class="mini" onclick='editAdmissionTest(${JSON.stringify(x).replace(/</g,'\u003c')})'>Edit</button> <button class="mini danger" onclick='deleteAdmissionTest("${esc(x['Test ID'])}")'>Delete</button></td></tr>`).join('')||'<tr><td colspan="10">No admission tests created yet.</td></tr>';
    if(sel?.value) await loadAdmissionCandidates(); else clearAdmissionTables();
  }catch(e){msg(e.message,'error');}
}
function clearAdmissionTables(){if($('admissionCandidateRows'))$('admissionCandidateRows').innerHTML='<tr><td colspan="11">Select an admission test first.</td></tr>';if($('admissionMeritRows'))$('admissionMeritRows').innerHTML='<tr><td colspan="9">Select an admission test first.</td></tr>';['adTotal','adSeats','adSelected','adWaiting','adVacant'].forEach(id=>{if($(id))$(id).textContent='0';});}
function selectAdmissionTest(id){admissionSelectedTest=id;if($('admissionTestSelect'))$('admissionTestSelect').value=id;loadAdmissionCandidates();}

async function toggleAdmissionStatus(id){
  const x=admissionTestsCache.find(t=>t['Test ID']===id); if(!x)return;
  const next=String(x.Status).toLowerCase()==='open'?'Closed':'Open';
  if(!confirm((next==='Open'?'Open':'Close')+' this admission test for students?'))return;
  try{await API.saveAdmissionTest(adminPin,{id,academicYear:x['Academic Year'],class:x.Class,trade:x.Trade,jobRole:x['Job Role'],testDate:x['Test Date'],totalSeats:x['Total Seats'],maxMarks:x['Max Marks'],selectionRule:x['Selection Rule'],status:next,notes:x.Notes});msg('Admission test '+next.toLowerCase()+'.','success');await loadAdmissionCenter();}catch(e){msg(e.message,'error');}
}
async function openAdmissionQuestions(testId){
  const test=admissionTestsCache.find(t=>t['Test ID']===testId); if(!test)return;
  try{
    const qs=await API.getAdmissionQuestions(adminPin,testId)||[];
    const rows=qs.map(q=>`<tr><td>${esc(q['Question No'])}</td><td>${esc(q.Question)}</td><td>${esc(q['Option A'])} | ${esc(q['Option B'])} | ${esc(q['Option C'])} | ${esc(q['Option D'])}</td><td>${String.fromCharCode(65+Number(q.Correct||0))}</td><td>${esc(q.Marks)}</td><td><button class="mini" onclick='editAdmissionQuestion(${JSON.stringify(q).replace(/</g,'\\u003c')})'>Edit</button> <button class="mini danger" onclick='deleteAdmissionQuestion("${esc(q['Question ID'])}","${esc(testId)}")'>Delete</button></td></tr>`).join('')||'<tr><td colspan="6">No questions added yet.</td></tr>';
    const body=`<div class="notice"><b>${esc(test['Academic Year'])} • ${esc(test.Class)} • ${esc(test.Trade)}</b><br>Students see this test only while its status is <b>Open</b>. Add questions before opening it.</div><div class="table-wrap"><table class="admin-table"><thead><tr><th>#</th><th>Question</th><th>Options</th><th>Correct</th><th>Marks</th><th>Action</th></tr></thead><tbody>${rows}</tbody></table></div>`;
    modal('Admission Question Bank',body,`<button class="btn secondary" onclick="closeModal()">Close</button><button class="btn primary" onclick='addAdmissionQuestion(${JSON.stringify(testId)})'>+ Add Question</button>`);
  }catch(e){msg(e.message,'error');}
}
function admissionQuestionForm(q={},testId=''){
  return `<div class="grid"><div class="field"><label>Question No.</label><input id="aqNo" type="number" min="1" value="${esc(q['Question No']||1)}"></div><div class="field"><label>Marks</label><input id="aqMarks" type="number" min="1" value="${esc(q.Marks||1)}"></div><div class="field" style="grid-column:1/-1"><label>Question</label><textarea id="aqQuestion" rows="3">${esc(q.Question||'')}</textarea></div><div class="field"><label>Option A</label><input id="aqA" value="${esc(q['Option A']||'')}"></div><div class="field"><label>Option B</label><input id="aqB" value="${esc(q['Option B']||'')}"></div><div class="field"><label>Option C</label><input id="aqC" value="${esc(q['Option C']||'')}"></div><div class="field"><label>Option D</label><input id="aqD" value="${esc(q['Option D']||'')}"></div><div class="field"><label>Correct Answer</label><select id="aqCorrect">${['A','B','C','D'].map((v,i)=>`<option value="${i}" ${Number(q.Correct||0)===i?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Explanation (optional)</label><input id="aqExplanation" value="${esc(q.Explanation||'')}"></div></div><input type="hidden" id="aqId" value="${esc(q['Question ID']||'')}"><input type="hidden" id="aqTestId" value="${esc(testId||q['Test ID']||'')}">`;
}
function addAdmissionQuestion(testId){modal('Add Admission Question',admissionQuestionForm({},testId),`<button class="btn secondary" onclick='openAdmissionQuestions(${JSON.stringify(testId)})'>Back</button><button class="btn primary" onclick="saveAdmissionQuestion()">Save Question</button>`);}
function editAdmissionQuestion(q){modal('Edit Admission Question',admissionQuestionForm(q,q['Test ID']),`<button class="btn secondary" onclick='openAdmissionQuestions(${JSON.stringify(q['Test ID'])})'>Back</button><button class="btn primary" onclick="saveAdmissionQuestion()">Save Changes</button>`);}
async function saveAdmissionQuestion(){
  const testId=$('aqTestId').value;
  showAdminActionLoading($('aqId').value?'Saving question changes…':'Adding question…');
  try{await API.saveAdmissionQuestion(adminPin,{id:$('aqId').value,testId,questionNo:$('aqNo').value,question:$('aqQuestion').value,optionA:$('aqA').value,optionB:$('aqB').value,optionC:$('aqC').value,optionD:$('aqD').value,correct:$('aqCorrect').value,explanation:$('aqExplanation').value,marks:$('aqMarks').value});msg($('aqId').value?'Question updated successfully.':'Question added successfully.','success');await openAdmissionQuestions(testId);}catch(e){msg(e.message,'error');}finally{hideAdminActionLoading();}
}
async function deleteAdmissionQuestion(id,testId){if(!confirm('Delete this question?'))return;try{await API.deleteAdmissionQuestion(adminPin,id);await openAdmissionQuestions(testId);}catch(e){msg(e.message,'error');}}

function admissionTestForm(x={}){return `<div class="grid"><div class="field"><label>Academic Year</label><input id="adYear" value="${esc(x['Academic Year']||'2026-27')}"></div><div class="field"><label>Class</label><select id="adClass">${['9th','10th','11th','12th'].map(v=>`<option ${v===x.Class?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Trade</label><select id="adTrade"><option ${x.Trade==='IT-ITeS'?'selected':''}>IT-ITeS</option><option ${x.Trade==='Agriculture'?'selected':''}>Agriculture</option></select></div><div class="field"><label>Job Role</label><input id="adJob" value="${esc(x['Job Role']||'')}" placeholder="Enter/select job role"></div><div class="field"><label>Test Date</label><input id="adDate" type="date" value="${esc(x['Test Date']||'')}"></div><div class="field"><label>Total Seats</label><input id="adSeatsInput" type="number" min="1" value="${esc(x['Total Seats']||30)}"></div><div class="field"><label>Maximum Marks</label><input id="adMax" type="number" min="1" value="${esc(x['Max Marks']||100)}"></div><div class="field"><label>Selection Rule</label><input id="adRule" value="${esc(x['Selection Rule']||'Highest marks / merit rank')}"></div><div class="field"><label>Status</label><select id="adStatus"><option>Open</option><option ${x.Status==='Closed'?'selected':''}>Closed</option><option ${x.Status==='Draft'?'selected':''}>Draft</option></select></div><div class="field"><label>Notes</label><input id="adNotes" value="${esc(x.Notes||'')}"></div></div><input type="hidden" id="adId" value="${esc(x['Test ID']||'')}"><div class="notice">Seat count is used automatically for Selected/Waiting. The merit calculation itself is based on marks/percentage; equal percentages receive the same rank.</div>`;}
function openAdmissionTestForm(x={}){modal(x['Test ID']?'Edit Admission Test':'Create Admission Test',admissionTestForm(x),'<button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveAdmissionTest()">Save Test</button>');}
function editAdmissionTest(x){openAdmissionTestForm(x)}
async function saveAdmissionTest(){
  const isEdit=!!$('adId').value;showAdminActionLoading(isEdit?'Updating admission test…':'Creating admission test…');
  try{const r=await API.saveAdmissionTest(adminPin,{id:$('adId').value,academicYear:$('adYear').value,class:$('adClass').value,trade:$('adTrade').value,jobRole:$('adJob').value,testDate:$('adDate').value,totalSeats:$('adSeatsInput').value,maxMarks:$('adMax').value,selectionRule:$('adRule').value,status:$('adStatus').value,notes:$('adNotes').value});admissionSelectedTest=r.id;closeModal();msg(isEdit?'Admission test updated successfully.':'Admission test created successfully.','success');await loadAdmissionCenter();selectAdmissionTest(r.id);}catch(e){msg(e.message,'error');}finally{hideAdminActionLoading();}
}
async function deleteAdmissionTest(id){if(!confirm('Delete this admission test and all its candidate/merit records? This action cannot be undone.'))return;try{await API.deleteAdmissionTest(adminPin,id);if(admissionSelectedTest===id)admissionSelectedTest='';msg('Admission test and linked records deleted.','success');loadAdmissionCenter();}catch(e){msg(e.message,'error');}}
function admissionCandidateForm(x={}){const t=admissionTestsCache.find(a=>a['Test ID']===admissionSelectedTest)||{};return `<div class="grid"><div class="field"><label>Admission Test</label><select id="acTest">${admissionTestsCache.map(a=>`<option value="${esc(a['Test ID'])}" ${a['Test ID']===(x['Test ID']||admissionSelectedTest)?'selected':''}>${esc(a['Academic Year'])} • ${esc(a.Class)} • ${esc(a.Trade)} • ${esc(a['Job Role'])}</option>`).join('')}</select></div><div class="field"><label>Application No.</label><input id="acApp" value="${esc(x['Application No']||'')}"></div><div class="field"><label>Roll Number</label><input id="acRoll" value="${esc(x['Roll Number']||'')}"></div><div class="field"><label>Student Name</label><input id="acName" value="${esc(x['Student Name']||'')}"></div><div class="field"><label>Father's Name</label><input id="acFather" value="${esc(x["Father's Name"]||'')}"></div><div class="field"><label>Mobile</label><input id="acMobile" inputmode="numeric" value="${esc(x.Mobile||'')}"></div><div class="field"><label>Test Marks</label><input id="acMarks" type="number" min="0" value="${esc(x.Marks??'')}"></div><div class="field"><label>Tie Breaker (optional)</label><input id="acTie" type="number" value="${esc(x['Tie Breaker']||0)}"></div><div class="field"><label>Notes</label><input id="acNotes" value="${esc(x.Notes||'')}"></div></div><input type="hidden" id="acId" value="${esc(x['Candidate ID']||'')}"><div class="notice">The maximum marks are taken from the selected test. Rank and Selected/Waiting status are recalculated automatically after every save/delete.</div>`;}
function openAdmissionCandidateForm(x={}){if(!admissionTestsCache.length)return msg('Create an admission test first.','error');modal(x['Candidate ID']?'Edit Candidate':'Add Admission Candidate',admissionCandidateForm(x),'<button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveAdmissionCandidate()">Save Candidate</button>');}
async function saveAdmissionCandidate(){try{const r=await API.saveAdmissionCandidate(adminPin,{id:$('acId').value,testId:$('acTest').value,applicationNo:$('acApp').value,rollNumber:$('acRoll').value,studentName:$('acName').value,fatherName:$('acFather').value,mobile:$('acMobile').value,marks:$('acMarks').value,tieBreaker:$('acTie').value,notes:$('acNotes').value});admissionSelectedTest=$('acTest').value;closeModal();msg('Candidate saved and merit recalculated.','success');await loadAdmissionCandidates();}catch(e){msg(e.message,'error');}}
async function loadAdmissionCandidates(){const tid=$('admissionTestSelect')?.value||admissionSelectedTest;if(!tid)return clearAdmissionTables();admissionSelectedTest=tid;const q=($('admissionSearch')?.value||'').trim().toLowerCase();try{const rows=await API.getAdmissionCandidates(adminPin,tid);const filtered=(rows||[]).filter(x=>!q||[x['Application No'],x['Roll Number'],x['Student Name'],x["Father's Name"]].some(v=>String(v||'').toLowerCase().includes(q)));$('admissionCandidateRows').innerHTML=filtered.map(x=>`<tr><td>${esc(x.Rank||'—')}</td><td>${esc(x['Application No'])}</td><td>${esc(x['Roll Number']||'—')}</td><td>${esc(x['Student Name'])}</td><td>${esc(x["Father's Name"])}</td><td>${esc(x.Trade)}</td><td>${esc(x['Job Role'])}</td><td>${esc(x.Marks)} / ${esc(x['Max Marks'])}</td><td>${esc(x.Percentage)}%</td><td><span class="badge">${esc(x.Status)}</span></td><td><button class="mini" onclick='openAdmissionCandidateForm(${JSON.stringify(x).replace(/</g,'\\u003c')})'>Edit</button> <button class="mini danger" onclick='deleteAdmissionCandidate("${esc(x['Candidate ID'])}")'>Delete</button></td></tr>`).join('')||'<tr><td colspan="11">No candidates found for this test.</td></tr>';await refreshAdmissionMerit();}catch(e){msg(e.message,'error');}}
async function refreshAdmissionMerit(){if(!admissionSelectedTest)return clearAdmissionTables();try{const r=await API.getAdmissionMerit(adminPin,admissionSelectedTest);admissionMeritCache=r.merit||[];$('adTotal').textContent=admissionMeritCache.length;$('adSeats').textContent=r.seats||0;$('adSelected').textContent=r.seatsFilled||0;$('adWaiting').textContent=Math.max(0,admissionMeritCache.length-(r.seatsFilled||0));$('adVacant').textContent=r.vacant||0;$('admissionMeritRows').innerHTML=admissionMeritCache.map(x=>`<tr><td>${esc(x.rank)}</td><td>${esc(x.applicationNo)}</td><td>${esc(x.rollNumber||'—')}</td><td>${esc(x.studentName)}</td><td>${esc(x.fatherName)}</td><td>${esc(x.marks)}</td><td>${esc(x.maxMarks)}</td><td>${esc(x.percentage)}%</td><td><span class="badge">${esc(x.status)}</span></td></tr>`).join('')||'<tr><td colspan="9">No merit records yet.</td></tr>';}catch(e){msg(e.message,'error');}}
async function deleteAdmissionCandidate(id){if(!confirm('Delete this candidate? Merit will be recalculated automatically.'))return;try{await API.deleteAdmissionCandidate(adminPin,id);msg('Candidate deleted and merit recalculated.','success');loadAdmissionCandidates();}catch(e){msg(e.message,'error');}}
function downloadAdmissionCSV(){if(!admissionMeritCache.length)return msg('No merit records to download.','error');const cols=['Rank','Application No.','Roll Number','Student Name',"Father's Name",'Marks','Max Marks','Percentage','Status','Trade','Job Role'];const rows=admissionMeritCache.map(x=>[x.rank,x.applicationNo,x.rollNumber,x.studentName,x.fatherName,x.marks,x.maxMarks,x.percentage,x.status,x.trade,x.jobRole]);const csv=[cols, ...rows].map(r=>r.map(csvEscape).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='Sandipani_Admission_Merit_List.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);msg('Merit CSV downloaded.','success');}
function printAdmissionMerit(){if(!admissionMeritCache.length)return msg('No merit records to print.','error');const t=admissionTestsCache.find(x=>x['Test ID']===admissionSelectedTest)||{};const w=window.open('','_blank');if(!w)return;const rows=admissionMeritCache.map(x=>`<tr><td>${esc(x.rank)}</td><td>${esc(x.applicationNo)}</td><td>${esc(x.rollNumber||'')}</td><td>${esc(x.studentName)}</td><td>${esc(x.fatherName)}</td><td>${esc(x.marks)}</td><td>${esc(x.maxMarks)}</td><td>${esc(x.percentage)}%</td><td>${esc(x.status)}</td></tr>`).join('');w.document.write(`<!doctype html><html><head><title>Admission Merit List</title><style>body{font-family:Arial;margin:30px;color:#111}h1,h2{text-align:center;margin:4px}.meta{text-align:center;margin:10px 0 20px;color:#444}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid #222;padding:7px;text-align:left}th{background:#eee}.sign{display:flex;justify-content:space-between;margin-top:80px}.sign div{width:35%;text-align:center}.sign small{display:block;margin-top:8px}</style></head><body><h1>Govt. Sandipani HSS School Damoh</h1><h2>Admission Test Merit List</h2><div class="meta">Academic Year: ${esc(t['Academic Year'])} • Class: ${esc(t.Class)} • Trade: ${esc(t.Trade)} • Job Role: ${esc(t['Job Role'])}<br>Test Date: ${esc(t['Test Date'])} • Total Seats: ${esc(t['Total Seats'])} • Maximum Marks: ${esc(t['Max Marks'])}</div><table><thead><tr><th>Rank</th><th>Application</th><th>Roll</th><th>Student</th><th>Father</th><th>Marks</th><th>Max</th><th>%</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table><div class="sign"><div><b>Signature of Teacher</b><small>________________________</small></div><div><b>Principal Seal & Signature</b><small>________________________</small></div></div><script>window.print()<\/script></body></html>`);w.document.close();}
